package com.osrstelemetry.plugin.navigation;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Precomputed walks between travel arrivals and destinations (canonical §28.10), generated by {@code RouteTableGenerator}
 * from the world collision map and the transitions with the {@link Pathfinder}, and bundled as
 * {@code navigation/routes.json}. The searches were unbounded, so a missing pair means no walk exists at all with the
 * transitions the data knows; a pair present but not allowed for an account is a different answer (locked).
 *
 * <p>Each pair keeps up to three variants, cheapest first: the best walk using any transition; the best one without
 * skill-gated transitions (agility shortcuts); the best one with no gated transition at all. An account takes the first
 * variant whose every transition it can use ({@link #best}).
 *
 * <p>Keys: a destination is {@code stop:<stop key>} or {@code node:<network entrance id>}; a start is
 * {@code arr:<transport id>} (where that teleport or hop lands) or {@code node:<id>}.
 *
 * <p>Immutable; thread-safe.
 */
public final class RouteTable
{
	public static final int SCHEMA = 1;
	static final String FILE = "/com/osrstelemetry/plugin/navigation/routes.json";

	/** One walk: its cost, its walked tiles and the transitions on it, in order. */
	public static final class Walk
	{
		private final int cost;
		private final int walkTiles;
		private final List<Transition> transitions;
		private final NavRequirement requirement;

		Walk(int cost, int walkTiles, List<Transition> transitions)
		{
			this.cost = cost;
			this.walkTiles = walkTiles;
			this.transitions = Collections.unmodifiableList(transitions);
			NavRequirement r = NavRequirement.NONE;
			for (Transition t : transitions)
			{
				r = r.and(t.requirement);
			}
			this.requirement = r;
		}

		/** Walking tiles plus each transition's duration (two tiles a tick). */
		public int getCost()
		{
			return cost;
		}

		public int getWalkTiles()
		{
			return walkTiles;
		}

		public List<Transition> getTransitions()
		{
			return transitions;
		}

		/** Everything this walk needs. */
		public NavRequirement getRequirement()
		{
			return requirement;
		}
	}

	/** routes.json. */
	static final class Doc
	{
		int schema;
		String transitions;
		String generatedFrom;
		/** key → snapped tile [x, y, plane] (starts) or goal tiles [[x, y, plane], ...] flattened (destinations). */
		Map<String, int[]> starts;
		Map<String, int[]> goals;
		/** destination key → whether its searches explored everything reachable (a missing start is then proven unreachable). */
		Map<String, Boolean> exhaustive;
		/** destination key → start key → variants, each [cost, walkTiles, transition index...]. */
		Map<String, Map<String, int[][]>> routes;
	}

	private final Doc doc;
	private final TransitionCatalog transitions;

	RouteTable(Doc doc, TransitionCatalog transitions)
	{
		this.doc = doc;
		this.transitions = transitions;
	}

	private static volatile RouteTable shared;
	/** The client's Gson, installed at startup (Plugin Hub: never a fresh instance), used to read the bundled table. */
	private static volatile Gson gson;

	/** Installs the Gson the bundled table is read with: the client's injected instance (tests pass their own). */
	public static void useGson(Gson clientGson)
	{
		if (clientGson != null)
		{
			gson = clientGson;
		}
	}

	/** The bundled table; throws when it is missing or was generated from different transition data (a build defect). */
	public static RouteTable bundled()
	{
		RouteTable t = shared;
		if (t == null)
		{
			synchronized (RouteTable.class)
			{
				t = shared;
				if (t == null)
				{
					Gson g = gson;
					if (g == null)
					{
						throw new IllegalStateException("RouteTable.useGson must be called with the client's Gson before the table is read");
					}
					t = load(g, TransitionCatalog.bundled());
					shared = t;
				}
			}
		}
		return t;
	}

	static RouteTable load(Gson gson, TransitionCatalog transitions)
	{
		try (InputStream in = RouteTable.class.getResourceAsStream(FILE))
		{
			if (in == null)
			{
				throw new IllegalStateException("Missing navigation/routes.json");
			}
			try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Doc d = gson.fromJson(r, Doc.class);
				if (d == null || d.schema != SCHEMA || d.routes == null)
				{
					throw new IllegalStateException("navigation/routes.json has no schema " + SCHEMA + " routes");
				}
				if (!fingerprint(transitions).equals(d.transitions))
				{
					throw new IllegalStateException("navigation/routes.json was generated from other transition data: regenerate it");
				}
				return new RouteTable(d, transitions);
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
		catch (JsonParseException e)
		{
			throw new IllegalStateException("Unreadable navigation/routes.json", e);
		}
	}

	/** Identifies the transition list the indices refer to. */
	public static String fingerprint(TransitionCatalog transitions)
	{
		long h = 1125899906842597L;
		for (Transition t : transitions.all())
		{
			h = 31 * h + (t.from + "/" + t.to + "/" + t.family + "/" + t.objectId + "/" + t.duration + "/" + t.requirement).hashCode();
		}
		return transitions.all().size() + ":" + Long.toHexString(h);
	}

	private final java.util.concurrent.ConcurrentHashMap<String, List<Walk>> cache = new java.util.concurrent.ConcurrentHashMap<>();

	/** Every walk known from {@code from} to {@code to}, cheapest first; empty when none exists. Cached (immutable). */
	public List<Walk> variants(String to, String from)
	{
		return cache.computeIfAbsent(to + "\u0000" + from, k -> build(to, from));
	}

	private List<Walk> build(String to, String from)
	{
		Map<String, int[][]> m = doc.routes.get(to);
		int[][] v = m == null ? null : m.get(from);
		if (v == null)
		{
			return Collections.emptyList();
		}
		List<Walk> out = new ArrayList<>(v.length);
		for (int[] row : v)
		{
			List<Transition> ts = new ArrayList<>();
			for (int i = 2; i < row.length; i++)
			{
				ts.add(transitions.all().get(row[i]));
			}
			out.add(new Walk(row[0], row[1], ts));
		}
		return Collections.unmodifiableList(out);
	}

	/** The cheapest walk the access allows, or null (none exists, or none is allowed). */
	public Walk best(String to, String from, NavAccess access)
	{
		for (Walk w : variants(to, from))
		{
			if (access.allows(w.getRequirement()))
			{
				return w;
			}
		}
		return null;
	}

	/**
	 * What the data establishes about walking from {@code from} to {@code to} with any transition: FOUND (a walk exists),
	 * UNREACHABLE (the destination's searches were exhaustive and never reached this start: proven), or DATA_UNAVAILABLE
	 * (the destination or start was not generated, or its search stopped early).
	 */
	public NavOutcome existence(String to, String from)
	{
		if (!doc.routes.containsKey(to) || doc.starts == null || !doc.starts.containsKey(from))
		{
			return NavOutcome.DATA_UNAVAILABLE;
		}
		if (!variants(to, from).isEmpty())
		{
			return NavOutcome.FOUND;
		}
		return doc.exhaustive != null && Boolean.TRUE.equals(doc.exhaustive.get(to)) ? NavOutcome.UNREACHABLE : NavOutcome.DATA_UNAVAILABLE;
	}

	/** Every start key the data knows (where each catalogue arrival was searched from). */
	public List<String> allStarts()
	{
		return doc.starts == null ? Collections.emptyList() : new ArrayList<>(doc.starts.keySet());
	}

	/** Whether the destination was generated at all. */
	public boolean hasDestination(String to)
	{
		return doc.routes.containsKey(to);
	}

	/** Every start with a walk to {@code to}. */
	public List<String> startsFor(String to)
	{
		Map<String, int[][]> m = doc.routes.get(to);
		return m == null ? Collections.emptyList() : new ArrayList<>(m.keySet());
	}

	public List<String> destinations()
	{
		return new ArrayList<>(doc.routes.keySet());
	}

	/** The tiles a destination is reached at (packed), or empty. */
	public int[] goals(String to)
	{
		int[] g = doc.goals == null ? null : doc.goals.get(to);
		if (g == null)
		{
			return new int[0];
		}
		int[] out = new int[g.length / 3];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = NavPoint.pack(g[3 * i], g[3 * i + 1], g[3 * i + 2]);
		}
		return out;
	}

	/** Where a start was searched from (its arrival snapped to a standable tile), or -1. */
	public int start(String from)
	{
		int[] s = doc.starts == null ? null : doc.starts.get(from);
		return s == null ? -1 : NavPoint.pack(s[0], s[1], s[2]);
	}

	Map<String, int[]> rawStarts()
	{
		return doc.starts == null ? new LinkedHashMap<>() : doc.starts;
	}
}
